// Refund workflow. Validates the request shape, simulates the gateway refund
// call and returns a reference. Authority checks already happened in the backend
// policy engine; this layer refuses anything that arrives malformed.
const body = $input.first().json.body ?? $input.first().json;
if (!body.transactionId || typeof body.amount !== 'number' || body.amount <= 0) {
  return [{ json: { refunded: false, error: 'Malformed refund request' } }];
}
return [{ json: {
  refunded: true,
  reference: 'RFND-' + Math.random().toString(16).slice(2, 10).toUpperCase(),
  transactionId: body.transactionId,
  amount: body.amount,
  settlementDays: 5,
  processedAt: new Date().toISOString(),
} }];
